// ================================================================
//            PROVIDED TEST HARNESS -- DO NOT EDIT THIS FILE
// ================================================================
// Tests part (a): my_write and my_exit from write.s.
//
// Input, first line:
//   write        the rest of the input is passed to my_write(buf, len)
//   exit N       calls my_exit(N)
// The call runs in a child process, so the harness can print its exit code.
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/wait.h>
#include <unistd.h>

long my_write(const char *buf, unsigned long len);
void my_exit(long code);

int main(void) {
    static char buf[4096];
    char cmd[64];
    if (!fgets(cmd, sizeof cmd, stdin)) return 1;
    int is_write = strncmp(cmd, "write", 5) == 0;
    long code = is_write ? 0 : atol(cmd + 4);
    unsigned long len = is_write ? fread(buf, 1, sizeof buf, stdin) : 0;
    fflush(stdout);

    pid_t pid = fork();
    if (pid == 0) {
        if (is_write) {
            long r = my_write(buf, len);
            printf("my_write returned %ld\n", r);
            fflush(stdout);
            _exit(0);
        }
        my_exit(code);
        printf("ERROR: my_exit returned\n");
        fflush(stdout);
        _exit(100);
    }
    int st;
    waitpid(pid, &st, 0);
    if (WIFEXITED(st)) printf("exit code %d\n", WEXITSTATUS(st));
    else printf("crashed (signal %d)\n", WTERMSIG(st));
    return 0;
}
